import { siteConfig } from "@/config/site.config";

const { locality, city } = siteConfig.contact.address;

/**
 * The site-wide social sharing image generated by `app/opengraph-image.tsx`.
 *
 * Exported for page metadata as well: a page that sets its own `openGraph`
 * object replaces the inherited one entirely (Next.js merges metadata
 * shallowly), image included, so per-page metadata must reference it
 * explicitly.
 */
export const defaultOgImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: `${siteConfig.name}: ${siteConfig.tagline} in ${locality}, ${city}`,
} as const;
